  -a, --all               Show all paths, including resources
      --no-name-check     Try to open all files, whatever their names
  -o, --output <OUTPUT>   Output: by default pretty summary tables but you can also output log lines as csv, json, or raw (as they appear in the log files) (default: tables)
      --silent-load       Don't print anything during load: no progress bar or file list
"#;
    print!("{}", help);
}

fn parse_args() -> Result<Args, String> {
    let mut a = Args::default();
    let raw: Vec<String> = env::args().skip(1).collect();
    let mut i = 0;

    fn take_value(args: &[String], i: &mut usize, name: &str) -> Result<String, String> {
        // Accept --name=value or next arg
        let cur = &args[*i];
        if let Some(eq) = cur.find('=') {
            let v = cur[eq+1..].to_string();
            *i += 1;
            return Ok(v);
        }
        *i += 1;
        if *i >= args.len() {
            return Err(format!("error: a value is required for '{}' but none was supplied", name));
        }
        let v = args[*i].clone();
        *i += 1;
        Ok(v)
    }

    while i < raw.len() {
        let arg = raw[i].clone();
        let base = arg.split('=').next().unwrap().to_string();
        match base.as_str() {
            "--help" | "-h" => { print_help(); std::process::exit(0); }
            "--version" => {
                println!("rhit {}", VERSION);
                std::process::exit(0);
            }
            "--color" => {
                let v = take_value(&raw, &mut i, "--color")?;
                a.color = match v.as_str() {
                    "auto" => ColorMode::Auto,
                    "yes" => ColorMode::Yes,
                    "no" => ColorMode::No,
                    other => return Err(format!("error: invalid value '{}' for --color", other)),
                };
            }
            "-k" | "--key" => {
                let v = take_value(&raw, &mut i, "--key")?;
                a.key = match v.as_str() {
                    "h" | "hits" => Key::Hits,
                    "b" | "bytes" => Key::Bytes,
                    other => return Err(format!("error: invalid value '{}' for --key", other)),
                };
            }
            "-l" | "--length" => {
                let v = take_value(&raw, &mut i, "--length")?;
                a.length = v.parse().map_err(|_| format!("error: invalid value '{}' for --length", v))?;
            }
            "-f" | "--fields" => {
                let v = take_value(&raw, &mut i, "--fields")?;
                a.fields = parse_fields(&v, &a.fields)?;
            }
            "-c" | "--changes" => { a.changes = true; i += 1; }
            "-d" | "--date" => { a.date = Some(take_value(&raw, &mut i, "--date")?); }
            "-i" | "--ip" => { a.ip = Some(take_value(&raw, &mut i, "--ip")?); }
            "-m" | "--method" => { a.method = Some(take_value(&raw, &mut i, "--method")?); }
            "-p" | "--path" => { a.path = Some(take_value(&raw, &mut i, "--path")?); }
            "-r" | "--referer" => { a.referer = Some(take_value(&raw, &mut i, "--referer")?); }
            "-s" | "--status" => { a.status = Some(take_value(&raw, &mut i, "--status")?); }
            "-t" | "--time" => { a.time = Some(take_value(&raw, &mut i, "--time")?); }
            "-a" | "--all" => { a.all = true; i += 1; }
            "--no-name-check" => { a.no_name_check = true; i += 1; }
            "-o" | "--output" => {
                let v = take_value(&raw, &mut i, "--output")?;
                a.output = match v.as_str() {
                    "t" | "table" | "tables" => OutputMode::Tables,
                    "c" | "csv" => OutputMode::Csv,
                    "j" | "json" => OutputMode::Json,
                    "r" | "raw" => OutputMode::Raw,
                    other => return Err(format!("error: invalid value '{}' for --output", other)),
                };
            }
            "--silent-load" => { a.silent_load = true; i += 1; }
            s if s.starts_with("--") => {
                return Err(format!("error: unexpected argument '{}' found\n\nUsage: executable [OPTIONS] [FILES]...", arg));
            }
            s if s.starts_with("-") && s.len() > 1 => {
                return Err(format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [FILES]...", arg, arg, arg));
            }
            _ => {
                a.files.push(arg);
                i += 1;
            }
        }
    }
    Ok(a)
}

fn parse_fields(v: &str, current: &[String]) -> Result<Vec<String>, String> {
    let all = ["date", "time", "method", "status", "ip", "ref", "path"];
    let v = v.trim();
    if v == "a" || v == "all" {
        return Ok(all.iter().map(|s| s.to_string()).collect());
    }
    // +x / -x to add/remove from current
    if v.starts_with('+') || v.starts_with('-') {
        let mut res: Vec<String> = current.to_vec();
        for tok in v.split(',') {
            let tok = tok.trim();
            if let Some(rest) = tok.strip_prefix('+') {
                if let Some(full) = expand_field(rest, &all) {
                    if !res.contains(&full.to_string()) { res.push(full.to_string()); }
                } else {
                    return Err(format!("error: invalid value '{}' for --fields", tok));
                }
            } else if let Some(rest) = tok.strip_prefix('-') {
                if let Some(full) = expand_field(rest, &all) {
                    res.retain(|x| x != full);
                } else {
                    return Err(format!("error: invalid value '{}' for --fields", tok));
                }
            } else if let Some(full) = expand_field(tok, &all) {
                if !res.contains(&full.to_string()) { res.push(full.to_string()); }
            } else {
                return Err(format!("error: invalid value '{}' for --fields", tok));
            }
        }
        return Ok(res);
    }
    // absolute list
    let mut res: Vec<String> = vec![];
    for tok in v.split(',') {
        let tok = tok.trim();
        if let Some(full) = expand_field(tok, &all) {
            if !res.contains(&full.to_string()) { res.push(full.to_string()); }
        } else {
            return Err(format!("error: invalid value '{}' for --fields", tok));
        }
    }
    Ok(res)
}

fn expand_field(tok: &str, all: &[&'static str]) -> Option<&'static str> {
    // match unique prefix
    let lc = tok.to_lowercase();
    if lc == "r" { return Some("ref"); }
    let mut found = None;
    for f in all {
        if f.starts_with(&lc) {
            if found.is_some() { return None; }
            found = Some(*f);
        }
    }
    found
}

#[derive(Debug, Clone)]
struct LogEntry {
    raw: String,
    date: String,        // yyyy/mm/dd
    time: String,        // hh:mm:ss
    remote: String,
    method: String,
    path: String,
    status: String,
    bytes: u64,
    referer: String,
}

fn parse_line(line: &str) -> Option<LogEntry> {
    // remote - - [date:time tz] "METHOD path HTTP/.." status bytes "referer" "ua"
    let raw = line.to_string();
    let b = line.as_bytes();
    let mut p = 0;
    fn skip_ws(b: &[u8], p: &mut usize) { while *p < b.len() && b[*p] == b' ' { *p += 1; } }
    fn take_token(b: &[u8], p: &mut usize) -> Option<String> {
        skip_ws(b, p);
        let start = *p;
        while *p < b.len() && b[*p] != b' ' { *p += 1; }
        if start == *p { return None; }
        Some(std::str::from_utf8(&b[start..*p]).ok()?.to_string())
    }
    fn take_bracket(b: &[u8], p: &mut usize) -> Option<String> {
        skip_ws(b, p);
        if *p >= b.len() || b[*p] != b'[' { return None; }
        *p += 1;
        let start = *p;
        while *p < b.len() && b[*p] != b']' { *p += 1; }
        if *p >= b.len() { return None; }
        let s = std::str::from_utf8(&b[start..*p]).ok()?.to_string();
        *p += 1; // skip ]
        Some(s)
    }
    fn take_quoted(b: &[u8], p: &mut usize) -> Option<String> {
        skip_ws(b, p);
        if *p >= b.len() || b[*p] != b'"' { return None; }
        *p += 1;
        let start = *p;
        while *p < b.len() && b[*p] != b'"' {
            if b[*p] == b'\\' && *p + 1 < b.len() { *p += 2; } else { *p += 1; }
        }
        if *p >= b.len() { return None; }
        let s = std::str::from_utf8(&b[start..*p]).ok()?.to_string();
        *p += 1;
        Some(s)
    }

    let remote = take_token(b, &mut p)?;
    let _ident = take_token(b, &mut p)?;
    let _user = take_token(b, &mut p)?;
    let dt = take_bracket(b, &mut p)?;
    let request = take_quoted(b, &mut p)?;
    let status = take_token(b, &mut p)?;
    let bytes = take_token(b, &mut p)?;
    let referer = take_quoted(b, &mut p).unwrap_or_else(|| "-".to_string());
    let _ua = take_quoted(b, &mut p);

    // parse date
    let (date, time) = parse_datetime(&dt)?;
    let bytes_num: u64 = bytes.parse().unwrap_or(0);
    let mut method = String::new();
    let mut path = String::new();
    // request = "METHOD path HTTP/x.y"
    let mut parts = request.splitn(3, ' ');
    if let Some(m) = parts.next() { method = m.to_string(); }
    if let Some(p) = parts.next() { path = p.to_string(); }

    Some(LogEntry { raw, date, time, remote, method, path, status, bytes: bytes_num, referer })
}

fn month_num(m: &str) -> Option<&'static str> {
    Some(match m {
        "Jan" => "01", "Feb" => "02", "Mar" => "03", "Apr" => "04",
        "May" => "05", "Jun" => "06", "Jul" => "07", "Aug" => "08",
        "Sep" => "09", "Oct" => "10", "Nov" => "11", "Dec" => "12",
        _ => return None,
    })
}

fn parse_datetime(s: &str) -> Option<(String, String)> {
    // "20/Aug/2023:12:34:56 +0200"
    let space = s.find(' ').unwrap_or(s.len());
    let dt = &s[..space];
    // dd/Mon/yyyy:hh:mm:ss
    let mut parts = dt.splitn(4, ':');
    let date_part = parts.next()?;
    let h = parts.next()?;
    let mi = parts.next()?;
    let se = parts.next()?;
    let mut dp = date_part.splitn(3, '/');
    let d = dp.next()?;
    let mo = dp.next()?;
    let y = dp.next()?;
    let month = month_num(mo)?;
    let date = format!("{}/{}/{:0>2}", y, month, d);
    let time = format!("{:0>2}:{:0>2}:{:0>2}", h, mi, se);
    Some((date, time))
}

fn is_resource(path: &str) -> bool {
    let lower = path.to_lowercase();
    // strip query
    let base = lower.split('?').next().unwrap_or(&lower);
    const RES_EXT: [&str; 20] = [
        ".css", ".js", ".mjs", ".png", ".jpg", ".jpeg", ".gif",
        ".webp", ".svg", ".ico", ".woff", ".woff2", ".ttf", ".otf",
        ".eot", ".map", ".webmanifest", ".mp4", ".webm", ".mp3",
    ];
    RES_EXT.iter().any(|e| base.ends_with(e))
}

fn collect_files(paths: &[String], no_name_check: bool) -> Result<Vec<PathBuf>, String> {
    let mut out: Vec<PathBuf> = vec![];
    let inputs: Vec<String> = if paths.is_empty() {
        vec![DEFAULT_LOG_PATH.to_string()]
    } else {
        paths.iter().cloned().collect()
    };
    for p in &inputs {
        let pb = Path::new(p);
        if !pb.exists() {
            return Err(format!("Error: PathNotFound({:?})", p));
        }
        if pb.is_dir() {
            let mut found_any = false;
            match fs::read_dir(pb) {
                Ok(rd) => {
                    for ent in rd.flatten() {
                        let ep = ent.path();
                        if ep.is_file() {
                            let fname = ep.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
                            if no_name_check || looks_like_nginx_log(&fname) {
                                out.push(ep);
                                found_any = true;
                            }
                        }
                    }
                }
                Err(_) => return Err(format!("Error: ReadDir({:?})", p)),
            }
            if !found_any && paths.is_empty() {
                return Err("Error: NoLogFileFound".to_string());
            }
            if !found_any {
                return Err("Error: NoLogFileFound".to_string());
            }
        } else {
            out.push(pb.to_path_buf());
        }
    }
    out.sort();
    Ok(out)
}

fn looks_like_nginx_log(name: &str) -> bool {
    // Accept access.log, access.log.N, access.log.N.gz etc.
    name.starts_with("access.log") ||
    name == "access_log" ||
    name.ends_with(".log") ||
    name.ends_with(".log.gz") ||
    (name.contains("access") && (name.ends_with(".gz") || name.ends_with(".log")))
}

fn open_reader(path: &Path) -> io::Result<Box<dyn BufRead>> {
    let name = path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    if name.ends_with(".gz") {
        // Use external gunzip via pipe
        let mut cmd = Command::new("gunzip");
        cmd.arg("-c").arg(path);
        cmd.stdout(Stdio::piped());
        let child = cmd.spawn()?;
        let out = child.stdout.ok_or_else(|| io::Error::other("gunzip stdout"))?;
        Ok(Box::new(BufReader::new(out)))
    } else {
        let f = fs::File::open(path)?;
        Ok(Box::new(BufReader::new(f)))
    }
}

fn read_all(files: &[PathBuf], silent: bool) -> (Vec<LogEntry>, usize) {
    let total = files.len();
    if !silent && total > 0 {
        // Print a simple progress indicator to stderr
        eprint!("reading {} file{}...\r", total, if total == 1 { "" } else { "s" });
        let _ = io::stderr().flush();
    }
    let mut entries: Vec<LogEntry> = vec![];
    for (idx, f) in files.iter().enumerate() {
        if let Ok(r) = open_reader(f) {
            for line in r.lines().flatten() {
                if let Some(e) = parse_line(&line) {
                    entries.push(e);
                }
            }
        }
        if !silent {
            eprint!("reading files... {}/{}\r", idx + 1, total);
            let _ = io::stderr().flush();
        }
    }
    if !silent {
        eprint!("\x1b[2K");
        let _ = io::stderr().flush();
        let msg = if total == 1 {
            format!("I've read {} file in \"{}\"\n", total, files[0].display())
        } else {
            format!("I've read {} files\n", total)
        };
        let _ = io::stderr().write_all(msg.as_bytes());
    }
    (entries, total)
}

fn apply_filters(entries: &[LogEntry], a: &Args) -> Vec<LogEntry> {
    let mut out: Vec<LogEntry> = vec![];
    for e in entries {
        if !a.all && is_resource(&e.path) { continue; }
        if let Some(ref m) = a.method {
            if !match_simple(m, &e.method) { continue; }
        }
        if let Some(ref ip) = a.ip {
            if !match_ip(ip, &e.remote) { continue; }
        }
        if let Some(ref pp) = a.path {
            if !match_substr(pp, &e.path) { continue; }
        }
        if let Some(ref rp) = a.referer {
            if !match_substr(rp, &e.referer) { continue; }
        }
        if let Some(ref sp) = a.status {
            if !match_status(sp, &e.status) { continue; }
        }
        if let Some(ref dp) = a.date {
            if !match_date(dp, &e.date) { continue; }
        }
        if let Some(ref tp) = a.time {
            if !match_time(tp, &e.time) { continue; }
        }
        out.push(e.clone());
    }
    out
}

fn match_simple(pat: &str, val: &str) -> bool {
    if let Some(rest) = pat.strip_prefix('!') {
        !val.eq_ignore_ascii_case(rest)
    } else {
        val.eq_ignore_ascii_case(pat)
    }
}

fn match_ip(pat: &str, val: &str) -> bool {
    if let Some(rest) = pat.strip_prefix('!') {
        val != rest
    } else if let Some(rest) = pat.strip_prefix('^') {
        val.starts_with(rest)
    } else {
        val == pat
    }
}

fn match_substr(pat: &str, val: &str) -> bool {
    // minimal: comma-separated terms, leading ! to negate
    let mut result = true;
    for t in pat.split(',') {
        let t = t.trim();
        if let Some(r) = t.strip_prefix('!') {
            if val.contains(r) { result = false; }
        } else {
            if !val.contains(t) { result = false; }
        }
    }
    result
}

fn match_status(pat: &str, val: &str) -> bool {
    let code: u32 = val.parse().unwrap_or(0);
    let mut include_any = false;
    let mut any_positive = false;
    for t in pat.split(',') {
        let t = t.trim();
        let (neg, body) = if let Some(r) = t.strip_prefix('!') { (true, r) } else { (false, t) };
        let matched = if body.ends_with("xx") && body.len() == 3 {
            let c = body.chars().next().unwrap();
            if let Some(d) = c.to_digit(10) { code / 100 == d } else { false }
        } else if let Some((a, b)) = body.split_once('-') {
            let a: u32 = a.parse().unwrap_or(0);
            let b: u32 = b.parse().unwrap_or(0);
            code >= a && code <= b
        } else {
            let v: u32 = body.parse().unwrap_or(u32::MAX);
            code == v
        };
        if !neg { any_positive = true; if matched { include_any = true; } }
        else if matched { return false; }
    }
    if any_positive { include_any } else { true }
}

fn match_date(pat: &str, val: &str) -> bool {
    // val is yyyy/mm/dd; pat may be yyyy or yyyy/mm or yyyy/mm/dd or range a-b or <x, >x, <=x, >=x
    fn norm(s: &str) -> String { s.replace('-', "/") }
    if let Some(rest) = pat.strip_prefix("<=") {
        return norm(val).as_str() <= norm(rest).as_str();
    }
    if let Some(rest) = pat.strip_prefix(">=") {
        return norm(val).as_str() >= norm(rest).as_str();
    }
    if let Some(rest) = pat.strip_prefix('<') {
        return norm(val).as_str() < norm(rest).as_str();
    }
    if let Some(rest) = pat.strip_prefix('>') {
        return norm(val).as_str() > norm(rest).as_str();
    }
    // range? only support a-b where - is between years or full dates (but dates contain /)
    // Try splitting at top-level '-' as a range separator
    if let Some((a, b)) = pat.split_once('-') {
        let a = norm(a);
        let b = norm(b);
        return norm(val).as_str() >= a.as_str() && norm(val).as_str() <= b.as_str();
    }
    let pat = norm(pat);
    let val = norm(val);
    val.starts_with(&pat)
}

fn match_time(pat: &str, val: &str) -> bool {
    // val is hh:mm:ss
    if let Some(rest) = pat.strip_prefix("<=") { return val <= &normalize_time(rest); }
    if let Some(rest) = pat.strip_prefix(">=") { return val >= &normalize_time(rest); }
    if let Some(rest) = pat.strip_prefix('<') { return val < &normalize_time(rest); }
    if let Some(rest) = pat.strip_prefix('>') { return val > &normalize_time(rest); }
    if let Some((a, b)) = pat.split_once('-') {
        return val >= &normalize_time(a) && val <= &normalize_time(b);
    }
    val.starts_with(&normalize_time(pat))
}

fn normalize_time(s: &str) -> String {
    // Accept hh, hh:mm, hh:mm:ss
    let parts: Vec<&str> = s.split(':').collect();
    let h = parts.get(0).copied().unwrap_or("00");
    let m = parts.get(1).copied().unwrap_or("00");
    let sec = parts.get(2).copied().unwrap_or("00");
    format!("{:0>2}:{:0>2}:{:0>2}", h, m, sec)
}

fn output_raw(entries: &[LogEntry]) {
    let stdout = io::stdout();
    let mut out = stdout.lock();
    for e in entries {
        let _ = writeln!(out, "{}", e.raw);
    }
}

fn csv_escape(s: &str) -> String {
    format!("\"{}\"", s.replace('"', "\"\""))
}

fn output_csv(entries: &[LogEntry]) {
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let _ = writeln!(out, "date,time,remote address,method,path,status,bytes sent,referer");
    for e in entries {
        let _ = writeln!(out, "{},{},{},{},{},{},{},{}",
            e.date, e.time, e.remote, e.method,
            csv_escape(&e.path), e.status, e.bytes, csv_escape(&e.referer));
    }
}

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn output_json(entries: &[LogEntry]) {
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let _ = writeln!(out, "[");
    for (i, e) in entries.iter().enumerate() {
        let _ = writeln!(out, "  {{");
        let _ = writeln!(out, "    \"date\": {},", json_escape(&e.date));
        let _ = writeln!(out, "    \"time\": {},", json_escape(&e.time));
        let _ = writeln!(out, "    \"remote_addr\": {},", json_escape(&e.remote));
        let _ = writeln!(out, "    \"method\": {},", json_escape(&e.method));
        let _ = writeln!(out, "    \"path\": {},", json_escape(&e.path));
        let _ = writeln!(out, "    \"status\": {},", json_escape(&e.status));
        let _ = writeln!(out, "    \"bytes_sent\": {},", e.bytes);
        let _ = writeln!(out, "    \"referer\": {}", json_escape(&e.referer));
        if i + 1 == entries.len() {
            let _ = writeln!(out, "  }}");
        } else {
            let _ = writeln!(out, "  }},");
        }
    }
    let _ = writeln!(out, "]");
}

// Basic table output using box-drawing characters
fn pad_left(s: &str, w: usize) -> String {
    if s.chars().count() >= w { s.to_string() } else {
        let pad = w - s.chars().count();
        format!("{}{}", " ".repeat(pad), s)
    }
}
fn pad_right(s: &str, w: usize) -> String {
    if s.chars().count() >= w { s.to_string() } else {
        let pad = w - s.chars().count();
        format!("{}{}", s, " ".repeat(pad))
    }
}

fn tbl_top(cols: &[usize]) -> String {
    let mut s = String::from("┌");
    for (i, c) in cols.iter().enumerate() {
        s.push_str(&"─".repeat(*c));
        if i + 1 < cols.len() { s.push('┬'); } else { s.push('┐'); }
    }
    s
}
fn tbl_mid(cols: &[usize]) -> String {
    let mut s = String::from("├");
    for (i, c) in cols.iter().enumerate() {
        s.push_str(&"─".repeat(*c));
        if i + 1 < cols.len() { s.push('┼'); } else { s.push('┤'); }
    }
    s
}
fn tbl_bot(cols: &[usize]) -> String {
    let mut s = String::from("└");
    for (i, c) in cols.iter().enumerate() {
        s.push_str(&"─".repeat(*c));
        if i + 1 < cols.len() { s.push('┴'); } else { s.push('┘'); }
    }
    s
}

fn output_tables(entries: &[LogEntry], a: &Args) {
    let stdout = io::stdout();
    let mut out = stdout.lock();

    let total_hits = entries.len() as u64;
    let total_bytes: u64 = entries.iter().map(|e| e.bytes).sum();
    if total_hits == 0 {
        let _ = writeln!(out, "no hit");
        return;
    }

    // Date range
    let mut dates: Vec<&str> = entries.iter().map(|e| e.date.as_str()).collect();
    dates.sort();
    dates.dedup();
    let first = dates.first().copied().unwrap_or("");
    let last = dates.last().copied().unwrap_or("");
    let _ = writeln!(out, "{} hits and {} from {} to {}", total_hits, total_bytes, first, last);

    // Per-date histogram table
    let mut per_date: BTreeMap<String, (u64, u64)> = BTreeMap::new();
    for e in entries {
        let ent = per_date.entry(e.date.clone()).or_insert((0, 0));
        ent.0 += 1;
        ent.1 += e.bytes;
    }
    print_date_table(&mut out, &per_date, a);

    // Status
    print_value_table(&mut out, "status", entries.iter().map(|e| (e.status.clone(), e.bytes)).collect(), a);

    // Referer
    print_value_table(&mut out, "referrer", entries.iter().map(|e| (e.referer.clone(), e.bytes)).collect(), a);

    // Path
    print_path_table(&mut out, entries, a);
}

fn print_date_table<W: Write>(out: &mut W, per_date: &BTreeMap<String, (u64, u64)>, a: &Args) {
    let max_v: u64 = per_date.values().map(|(h, b)| if a.key == Key::Hits { *h } else { *b }).max().unwrap_or(1).max(1);
    let w_date = 10usize;
    let w_hits = 4.max(per_date.values().map(|(h, _)| h.to_string().len()).max().unwrap_or(4));
    let w_bytes = 5.max(per_date.values().map(|(_, b)| b.to_string().len()).max().unwrap_or(5));
    let hist_w: usize = 20;
    let cols = [w_date, w_hits, w_bytes, hist_w];
    let _ = writeln!(out, "{}", tbl_top(&cols));
    let _ = writeln!(out, "│{}│{}│{}│{}│",
        pad_center("date", w_date),
        pad_center("hits", w_hits),
        pad_center("bytes", w_bytes),
        pad_right(&format!("0{}{}", " ".repeat(hist_w - 2), max_v), hist_w));
    let _ = writeln!(out, "{}", tbl_mid(&cols));
    for (d, (h, b)) in per_date {
        let v = if a.key == Key::Hits { *h } else { *b };
        let bar = ((v as f64) / (max_v as f64) * hist_w as f64).round() as usize;
        let bar_str = format!("{}{}", "█".repeat(bar), " ".repeat(hist_w - bar));
        let _ = writeln!(out, "│{}│{}│{}│{}│",
            pad_right(d, w_date),
            pad_left(&h.to_string(), w_hits),
            pad_left(&b.to_string(), w_bytes),
            bar_str);
    }
    let _ = writeln!(out, "{}", tbl_bot(&cols));
}

fn pad_center(s: &str, w: usize) -> String {
    let l = s.chars().count();
    if l >= w { return s.to_string(); }
    let total = w - l;
    let left = total / 2;
    let right = total - left;
    format!("{}{}{}", " ".repeat(left), s, " ".repeat(right))
}

fn print_value_table<W: Write>(out: &mut W, label: &str, entries: Vec<(String, u64)>, a: &Args) {
    let total_hits = entries.len() as u64;
    let total_bytes: u64 = entries.iter().map(|(_, b)| *b).sum();
    let _ = total_bytes;
    let mut map: BTreeMap<String, (u64, u64)> = BTreeMap::new();
    for (k, b) in &entries {
        let e = map.entry(k.clone()).or_insert((0, 0));
        e.0 += 1; e.1 += *b;
    }
    let mut rows: Vec<(String, u64, u64)> = map.into_iter().map(|(k, (h, b))| (k, h, b)).collect();
    rows.sort_by(|x, y| match a.key { Key::Hits => y.1.cmp(&x.1), Key::Bytes => y.2.cmp(&x.2) }.then(x.0.cmp(&y.0)));
    let n = rows.len();
    // Counter label: "paths", "status codes", ...
    let count_phrase = match label {
        "status" => format!("{} HTTP status codes. ", n),
        "referrer" => format!("{} referrers. ", n),
        _ => format!("{} {}s. ", n, label),
    };
    let _ = writeln!(out, "{}", count_phrase);
    let max_rows = match a.length { 0 => 10, 1 => 30, 2 => 60, 3 => 100, 4 => 200, 5 => 500, _ => usize::MAX };
    rows.truncate(max_rows);
    let w_num = 3.max(rows.len().to_string().len());
    let w_lbl = label.len().max(rows.iter().map(|r| r.0.chars().count()).max().unwrap_or(0));
    let w_hits = 4.max(rows.iter().map(|r| r.1.to_string().len()).max().unwrap_or(4));
    let w_bytes = 5.max(rows.iter().map(|r| r.2.to_string().len()).max().unwrap_or(5));
    let w_pct = 5;
    let cols = [w_num, w_lbl, w_hits, w_pct, w_bytes];
    let _ = writeln!(out, "{}", tbl_top(&cols));
    let _ = writeln!(out, "│{}│{}│{}│{}│{}│",
        pad_center("#", w_num),
        pad_right(label, w_lbl),
        pad_center("hits", w_hits),
        pad_center("%", w_pct),
        pad_right("bytes", w_bytes));
    let _ = writeln!(out, "{}", tbl_mid(&cols));
    for (i, r) in rows.iter().enumerate() {
        let pct = 100.0 * (r.1 as f64) / (total_hits as f64);
        let _ = writeln!(out, "│{}│{}│{}│{}│{}│",
            pad_left(&format!("{}", i + 1), w_num),
            pad_right(&r.0, w_lbl),
            pad_left(&r.1.to_string(), w_hits),
            pad_left(&format!("{:.1}%", pct), w_pct),
            pad_left(&r.2.to_string(), w_bytes));
    }
    let _ = writeln!(out, "{}", tbl_bot(&cols));
}

fn print_path_table<W: Write>(out: &mut W, entries: &[LogEntry], a: &Args) {
    let total_hits = entries.len() as u64;
    let mut map: BTreeMap<String, (u64, u64)> = BTreeMap::new();
    for e in entries {
        let r = map.entry(e.path.clone()).or_insert((0, 0));
        r.0 += 1; r.1 += e.bytes;
    }
    let mut rows: Vec<(String, u64, u64)> = map.into_iter().map(|(k, (h, b))| (k, h, b)).collect();
    rows.sort_by(|x, y| match a.key { Key::Hits => y.1.cmp(&x.1), Key::Bytes => y.2.cmp(&x.2) }.then(x.0.cmp(&y.0)));
    let n = rows.len();
    let preface = if a.all {
        format!("{} paths. \n", n)
    } else {
        format!("{} paths (excluding resources like images, css, \netc.). \n", n)
    };
    let _ = out.write_all(preface.as_bytes());

    let max_rows = match a.length { 0 => 10, 1 => 30, 2 => 60, 3 => 100, 4 => 200, 5 => 500, _ => usize::MAX };
    rows.truncate(max_rows);
    let w_num = 3.max(rows.len().to_string().len());
    let w_lbl = "path".len().max(rows.iter().map(|r| r.0.chars().count()).max().unwrap_or(0));
    let w_hits = 4.max(rows.iter().map(|r| r.1.to_string().len()).max().unwrap_or(4));
    let w_bytes = 5.max(rows.iter().map(|r| r.2.to_string().len()).max().unwrap_or(5));
    let w_pct = 5;
    let cols = [w_num, w_lbl, w_hits, w_pct, w_bytes];
    let _ = writeln!(out, "{}", tbl_top(&cols));
    let _ = writeln!(out, "│{}│{}│{}│{}│{}│",
        pad_center("#", w_num),
        pad_right("path", w_lbl),
        pad_center("hits", w_hits),
        pad_center("%", w_pct),
        pad_right("bytes", w_bytes));
    let _ = writeln!(out, "{}", tbl_mid(&cols));
    for (i, r) in rows.iter().enumerate() {
        let pct = 100.0 * (r.1 as f64) / (total_hits as f64);
        let _ = writeln!(out, "│{}│{}│{}│{}│{}│",
            pad_left(&format!("{}", i + 1), w_num),
            pad_right(&r.0, w_lbl),
            pad_left(&r.1.to_string(), w_hits),
            pad_left(&format!("{:.1}%", pct), w_pct),
            pad_left(&r.2.to_string(), w_bytes));
    }
    let _ = writeln!(out, "{}", tbl_bot(&cols));
}

fn run() -> ExitCode {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => { eprintln!("{}", e); return ExitCode::from(2); }
    };

    // Resolve files
    let files = match collect_files(&args.files, args.no_name_check) {
        Ok(f) if !f.is_empty() => f,
        Ok(_) => {
            if args.files.is_empty() {
                eprintln!("No nginx log found at default location, do you have nginx set up?");
                eprintln!("If necessary, provide the path to the log file(s) as argument.");
                eprintln!("More information with 'rhit --help'.");
                eprintln!("Error: NoLogFileFound");
            } else {
                eprintln!("Error: NoLogFileFound");
            }
            return ExitCode::from(1);
        }
        Err(e) => {
            if args.files.is_empty() {
                eprintln!("No nginx log found at default location, do you have nginx set up?");
                eprintln!("If necessary, provide the path to the log file(s) as argument.");
                eprintln!("More information with 'rhit --help'.");
            }
            eprintln!("{}", e);
            return ExitCode::from(1);
        }
    };

    let (entries, _n) = read_all(&files, args.silent_load);
    let filtered = apply_filters(&entries, &args);

    match args.output {
        OutputMode::Raw => output_raw(&filtered),
        OutputMode::Csv => output_csv(&filtered),
        OutputMode::Json => output_json(&filtered),
        OutputMode::Tables => output_tables(&filtered, &args),
    }
    ExitCode::from(0)
}

fn main() -> ExitCode {
    run()
}
